import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("tree audit", () => {
  test("tree audit", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.loadSheet(pg_uma, `${sheet}-c`);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    const p_cy = ui.must(await ui.addPerson(pg_uma, {"name": "Cy", "grade": "A"}));
    const c_cy_0 = ui.must(await ui.addClaim(pg_uma, p_cy, {"amount": "1.00"}));
    expect(await ui.claimAction(pg_uma, c_cy_0, "open")).toBe(true);
    await ui.loadSheet(pg_uma, `${sheet}-cc`);
    await ui.setToday(pg_uma, "2026-03-10");
    const p_cy_2 = ui.must(await ui.addPerson(pg_uma, {"name": "Cy", "grade": "B"}));
    await ui.setSetting(pg_uma, "parent", `${sheet}-c`);
    await ui.loadSheet(pg_uma, sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
    const p_cy_3 = ui.must(await ui.addPerson(pg_uma, {"name": "Cy", "grade": "C"}));
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    const c_cy_0_2 = ui.must(await ui.addClaim(pg_uma, p_cy_3, {"amount": "2.00"}));
    await ui.loadSheet(pg_uma, `${sheet}-c`);
    await ui.setSetting(pg_uma, "parent", `${sheet}`);
    await ui.loadSheet(pg_uma, sheet);
    await ui.expectAuditView(pg_uma, "Cy", [
      `CLAIM_ADDED sheet=${sheet} by=uma person=Cy amount=2.00 date=2026-03-10`,
      `ROLLUP sheet=${sheet} by=uma person=Cy claimed=0.00 due-total=n/a overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Cy grade=C`,
      `ROLLUP sheet=${sheet}-c by=uma person=Cy claimed=1.00 due-total=1.00 overdue-total=0.00`,
      `CLAIM_OPENED sheet=${sheet}-c by=uma person=Cy amount=1.00 date=2026-03-10 number=1`,
      `CLAIM_ADDED sheet=${sheet}-c by=uma person=Cy amount=1.00 date=2026-03-10`,
      `ROLLUP sheet=${sheet}-c by=uma person=Cy claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet}-c by=uma name=Cy grade=A`,
      `ROLLUP sheet=${sheet}-cc by=uma person=Cy claimed=0.00 due-total=n/a overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet}-cc by=uma name=Cy grade=B`
    ]);
    await ui.expectAuditView(pg_uma, "ada", [
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ada grade=A`
    ]);
    await ui.expectAuditView(pg_uma, "", [
      `CLAIM_ADDED sheet=${sheet} by=uma person=Cy amount=2.00 date=2026-03-10`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ada grade=A`,
      `ROLLUP sheet=${sheet} by=uma person=Cy claimed=0.00 due-total=n/a overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Cy grade=C`,
      `RATE_SET sheet=${sheet} by=uma grade=A rate=20.00`
    ]);
    await ui.loadSheet(pg_uma, `${sheet}-c`);
    await ui.expectAuditView(pg_uma, "cy", [
      `ROLLUP sheet=${sheet}-c by=uma person=Cy claimed=1.00 due-total=1.00 overdue-total=0.00`,
      `CLAIM_OPENED sheet=${sheet}-c by=uma person=Cy amount=1.00 date=2026-03-10 number=1`,
      `CLAIM_ADDED sheet=${sheet}-c by=uma person=Cy amount=1.00 date=2026-03-10`,
      `ROLLUP sheet=${sheet}-c by=uma person=Cy claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet}-c by=uma name=Cy grade=A`,
      `ROLLUP sheet=${sheet}-cc by=uma person=Cy claimed=0.00 due-total=n/a overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet}-cc by=uma name=Cy grade=B`
    ]);
    await ui.refresh(pg_uma);
    await ui.expectAudit(`${sheet}-c`, [
      `RATE_SET sheet=${sheet}-c by=uma grade=A rate=10.00`,
      `PERSON_ADDED sheet=${sheet}-c by=uma name=Cy grade=A`,
      `ROLLUP sheet=${sheet}-c by=uma person=Cy claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `CLAIM_ADDED sheet=${sheet}-c by=uma person=Cy amount=1.00 date=2026-03-10`,
      `CLAIM_OPENED sheet=${sheet}-c by=uma person=Cy amount=1.00 date=2026-03-10 number=1`,
      `ROLLUP sheet=${sheet}-c by=uma person=Cy claimed=1.00 due-total=1.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet}-c by=uma claimed-total=1.00 due-total=1.00 overdue-total=0.00`,
      `SETTING_CHANGED sheet=${sheet}-c by=uma key=parent value=${sheet}`
    ]);
  });
  test("tree audit scenario 1", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-04-05");
    expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
    await ui.setSetting(pg_uma, "terms", "10");
    await ui.setSetting(pg_uma, "late-pct", "10.00");
    await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
    await ui.setSetting(pg_uma, "cap", "2.00");
    await ui.setSetting(pg_uma, "perm-open", "steward");
    expect(await ui.setRole(pg_uma, "vic", "viewer")).toBe(true);
    await ui.setSetting(pg_uma, "grace-days", "3");
    await ui.setSetting(pg_uma, "note-threshold", "2.50");
    expect(await ui.addVoidReason(pg_uma, "error")).toBe(true);
    expect(await ui.addVoidReason(pg_uma, "dup")).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "20.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "7.50", "from": "2026-03-01"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
    const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B"}));
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A", "contact": " Ada@x "}));
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B", "contact": "ben@x", "tags": "b, a"}));
    expect(await ui.statement(pg_uma, p_ben)).toBe(true);
    const pg_wes = await ui.userPage(browser, "wes", sheet);
    expect(await ui.unstate(pg_wes, p_ben)).toBe(true);
    expect(await ui.statementAsOf(pg_wes, p_ben, "2026-03-15")).toBe(false);
    await ui.setToday(pg_wes, "2026-05-13");
    await ui.expectAuditView(pg_wes, "Cam", [
      `SNAPSHOT sheet=${sheet} by=wes name=Cam due-total=0.00`,
      `ROLLUP sheet=${sheet} by=uma person=Cam claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Cam grade=B`
    ]);
    expect(await ui.bulkGrade(pg_wes, [p_ada, p_ben], {"grade": "C", "from": "2026-03-28"})).toBe(2);
    expect(await ui.inlineGrade(pg_wes, p_ada, "A")).toBe(true);
    await ui.refresh(pg_wes);
    await expect(pg_wes.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("0.00");
    await expect(pg_wes.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("0.00");
    await expect(pg_wes.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("0.00");
    await expect(pg_wes.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("0.00");
    await expect(pg_wes.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("0.00");
    await expect(pg_wes.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("0.00");
    await expect(pg_wes.getByTestId("rollup-claimed-total")).toHaveText("0.00");
    await expect(pg_wes.getByTestId("rollup-due-total")).toHaveText("0.00");
    await expect(pg_wes.getByTestId("rollup-overdue-count")).toHaveText("0");
    await expect(pg_wes.getByTestId("rollup-overdue-total")).toHaveText("0.00");
    await expect(pg_wes.getByTestId("rollup-settled-total")).toHaveText("0.00");
    await expect(pg_wes.getByTestId("rollup-open-total")).toHaveText("0.00");
    await expect(pg_wes.getByTestId("bulk-settle-batch")).toHaveText("");
    await expect(pg_wes.getByTestId("rollup-cut-total")).toHaveText("0.00");
    await expect(pg_wes.getByTestId("header-people-count")).toHaveText("3");
    await expect(pg_wes.getByTestId("header-claims-DRAFT-count")).toHaveText("0");
    await expect(pg_wes.getByTestId("header-claims-OPEN-count")).toHaveText("0");
    await expect(pg_wes.getByTestId("header-claims-PENDING-count")).toHaveText("0");
    await expect(pg_wes.getByTestId("header-claims-SETTLED-count")).toHaveText("0");
    await expect(pg_wes.getByTestId("header-claims-VOID-count")).toHaveText("0");
    await expect(pg_wes.getByTestId("header-due-total")).toHaveText("0.00");
    await expect(pg_wes.getByTestId("header-overdue-total")).toHaveText("0.00");
    await expect(pg_wes.getByTestId("my-due-total")).toHaveText("");
    await expect(pg_wes.getByTestId("my-overdue-total")).toHaveText("");
    expect(await ui.inlineGrade(pg_wes, p_ben, "A")).toBe(true);
    expect(await ui.editPerson(pg_wes, p_ben, {"grade": "C", "gradeFrom": "2026-03-01"}, {"grade": "A"})).toBe(true);
    expect(await ui.watch(pg_wes, p_ada, true)).toBe(true);
    await ui.refresh(pg_wes);
    expect(await ui.periodAction(pg_wes, "P2", "reopen")).toBe(true);
    expect(await ui.addAlias(pg_wes, p_cam, " ada ")).toBe(false);

